import { useState } from "react";

import { useAuthStore } from "@/store/auth.store";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

type LoginCardProps = {
  onSuccess?: () => void;
};

export default function LoginCard({ onSuccess }: LoginCardProps) {
  const login = useAuthStore((state) => state.login);
  const loading = useAuthStore((state) => state.loading);
  const error = useAuthStore((state) => state.error);
  const [form, setForm] = useState({
    username: "",
    password: "",
    twoFactorCode: ""
  });

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    await login({
      username: form.username,
      password: form.password,
      twoFactorCode: form.twoFactorCode || undefined
    });

    const { token, error: loginError } = useAuthStore.getState();
    if (token && !loginError) {
      onSuccess?.();
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Sign in to Casemove</CardTitle>
        <CardDescription>
          Sign in with your Steam credentials (MVP).
        </CardDescription>
      </CardHeader>
      <form onSubmit={handleSubmit}>
        <CardContent className="grid gap-4">
          <div className="grid gap-2">
            <Label htmlFor="username">Username</Label>
            <Input
              id="username"
              onChange={(event) =>
                setForm((prev) => ({ ...prev, username: event.target.value }))
              }
              type="text"
              value={form.username}
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              onChange={(event) =>
                setForm((prev) => ({ ...prev, password: event.target.value }))
              }
              type="password"
              value={form.password}
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="twoFactorCode">Two-factor code</Label>
            <Input
              id="twoFactorCode"
              onChange={(event) =>
                setForm((prev) => ({
                  ...prev,
                  twoFactorCode: event.target.value
                }))
              }
              type="text"
              value={form.twoFactorCode}
            />
          </div>
          {error ? <p className="text-sm text-[var(--danger)]">{error}</p> : null}
        </CardContent>
        <CardFooter>
          <Button className="w-full" disabled={loading} type="submit">
            {loading ? "Signing in..." : "Sign in"}
          </Button>
        </CardFooter>
      </form>
    </Card>
  );
}
