import { create } from "zustand";

import { login as loginRequest } from "@/lib/api-client/auth";

type SteamStatus = "idle" | "connected" | "pending" | "error";

type LoginPayload = {
  username: string;
  password: string;
  twoFactorCode?: string;
};

type AuthState = {
  token: string | null;
  steamStatus: SteamStatus;
  loading: boolean;
  error: string | null;
  setToken: (token: string) => void;
  setSteamStatus: (status: SteamStatus) => void;
  setError: (message: string | null) => void;
  initFromStorage: () => void;
  login: (payload: LoginPayload) => Promise<void>;
};

export const useAuthStore = create<AuthState>((set) => ({
  token: null,
  steamStatus: "idle",
  loading: false,
  error: null,
  setToken: (token) => {
    set({ token });
    localStorage.setItem("casemove_token", token);
  },
  setSteamStatus: (status) => set({ steamStatus: status }),
  setError: (message) => set({ error: message }),
  initFromStorage: () => {
    const token = localStorage.getItem("casemove_token");
    if (token) {
      set({ token });
    }
  },
  login: async (payload) => {
    set({ loading: true, error: null });

    try {
      const result = await loginRequest(payload);
      set({ token: result.token, steamStatus: "connected", loading: false });
    } catch (error) {
      set({
        error: error instanceof Error ? error.message : "Login failed",
        steamStatus: "error",
        loading: false
      });
    }
  }
}));
